sub_steps.draft_rules:
spec(I, F, S) :- node(I, "IMPORT"), attr(I, "name", S), attr(I, "file", F).
@materialize(edge_type = "IMPORTS_FROM", mode = "additive", meta(resolvedPath))
import_module(I, M, R) :- resolved(I, R), node(M, "MODULE"), attr(M, "file", R).

% post strip_prefix + path_resolve:
@materialize(edge_type = "RE_EXPORTS", mode = "additive", meta(resolvedPath))
star_reexport(E, M, R) :- node(E, "EXPORT"), attr(E, "name", N), starts_with(N, "*:"), strip_prefix(N, "*:", S), attr(E, "file", F), path_resolved_any(F, S, R), node(M, "MODULE"), attr(M, "file", R).
